#include <iostream>
using namespace std;

struct Node {
	int data;
	Node * next;
};

int main () {
	Node * top = NULL;
	for (int i = 1; i <= 3; i++) {
		Node * n = new Node;
		n->data = i;
		n->next = top;
		top = n;
	}
	for (Node * c = top; c != NULL; c = c->next) cout << c->data << " ";
	cout << endl;
	while (top != NULL) { Node * t = top; top = top->next; delete t; }
	return 0;
}

#include <iostream>
using namespace std;

struct Node { int data; Node * next; };

void push (Node * & top, int v) {
	Node * n = new Node;
	n->data = v;
	n->next = top;
	top = n;
}

int main () {
	Node * top = NULL;
	push (top, 1); push (top, 2);
	cout << top->data << top->next->data << endl;
	delete top->next; delete top;
	return 0;
}

