#include <iostream>
using namespace std;

struct Point { int x, y; };
struct Line { Point a, b; };

Point mid (Line L) {
	Point m;
	m.x = (L.a.x + L.b.x) / 2;
	m.y = (L.a.y + L.b.y) / 2;
	return m;
}

int main () {
	Line ls[2] = {{{0, 0}, {4, 6}}, {{2, 2}, {2, 8}}};
	Point m = mid (ls[1]);
	cout << m.x << "," << m.y << endl;
	return 0;
}

